#!/usr/bin/env python3
# GENERATED by scripts/sync.py from core/scripts/statement.py. Edit the source in core/, then run: python scripts/sync.py
"""Bank statement exports for HouseholdBot: read, sum to the grosz, find recurring payments.

Reads a CSV export from a bank: the encoding (UTF-8 with or without BOM,
Windows-1250, ISO-8859-2), the delimiter, any preamble lines before the
header, and the columns (Polish and English names) are detected. Every
transaction is normalised and every sum is made with Decimal. Account, card
and PESEL numbers in descriptions are masked. Standard library only; every
command prints one JSON object.

Examples:
  python3 statement.py parse export.csv
  python3 statement.py summary export.csv --household ./household --lang pl
  python3 statement.py recurring export.csv --household ./household
  python3 statement.py add-rule ./household --match "Kowalski Jan" --category housing --approved-by Anna
"""
from __future__ import annotations

import argparse
import csv
import io
import json
import re
import statistics
import sys
from collections import defaultdict
from datetime import date, datetime, timedelta
from decimal import Decimal, InvalidOperation
from pathlib import Path

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))
sys.dont_write_bytecode = True
import dates  # noqa: E402
import record  # noqa: E402

VERSION = "1.1.0"
CATEGORIES_FILE = HERE.parent / "money" / "categories.json"
HOUSEHOLD_RULES = Path("registers") / "category-rules.json"
ENCODINGS = ["utf-8-sig", "cp1250", "iso-8859-2"]
DELIMITERS = [";", ",", "\t", "|"]
CENT = Decimal("0.01")

COLUMNS = {
    # field: names a bank may use, folded (lower case, no Polish letters, no '#')
    "date": ["data operacji", "data transakcji", "data zlecenia", "data", "date", "transaction date",
             "operation date", "booking date", "data ksiegowania", "value date", "data waluty"],
    "amount": ["kwota", "kwota operacji", "kwota transakcji", "kwota w walucie rachunku", "amount",
               "wartosc", "kwota pln"],
    "debit": ["obciazenia", "obciazenie", "kwota obciazenia", "wydatki", "debit", "wyplaty", "money out"],
    "credit": ["uznania", "uznanie", "kwota uznania", "wplywy", "credit", "wplaty", "money in"],
    "currency": ["waluta", "currency", "waluta rachunku"],
    "description": ["opis operacji", "opis transakcji", "tytul", "tytul operacji", "tytul przelewu",
                    "opis", "description", "title", "szczegoly", "details", "reference"],
    "counterparty": ["nadawca/odbiorca", "nadawca / odbiorca", "kontrahent", "nazwa kontrahenta",
                     "dane kontrahenta", "odbiorca/zleceniodawca", "odbiorca", "nadawca", "counterparty",
                     "payee", "beneficiary", "merchant", "nazwa odbiorcy"],
    "balance": ["saldo po operacji", "saldo po transakcji", "saldo ksiegowe", "saldo", "balance",
                "balance after"],
    "type": ["typ transakcji", "rodzaj operacji", "typ operacji", "typ", "type", "kategoria banku"],
}
DATE_FORMATS = ["%Y-%m-%d", "%d.%m.%Y", "%d-%m-%Y", "%d/%m/%Y", "%Y.%m.%d", "%Y/%m/%d"]


class StatementError(Exception):
    """The file cannot be read as a statement."""


# --------------------------------------------------------------------------
# Reading
# --------------------------------------------------------------------------

def fold(text: str) -> str:
    return record.fold(text or "").replace("#", "").strip()


def read_text(path: Path) -> tuple[str, str]:
    raw = path.read_bytes()
    for enc in ENCODINGS:
        try:
            return raw.decode(enc), enc
        except UnicodeDecodeError:
            continue
    raise StatementError(f"{path.name}: unknown text encoding")


def match_column(cell: str) -> str | None:
    c = fold(cell).strip(" :\"'")
    for field, names in COLUMNS.items():
        if c in names:
            return field
    return None


def find_header(lines: list[str]) -> tuple[int, str, dict]:
    """The header row, its delimiter and the column map, chosen by how many columns it names."""
    best = (-1, ";", {}, 0)
    for idx, line in enumerate(lines[:60]):
        for delim in DELIMITERS:
            if delim not in line:
                continue
            cells = next(csv.reader([line], delimiter=delim))
            mapping: dict[str, int] = {}
            extra_text: list[int] = []
            for col, cell in enumerate(cells):
                field = match_column(cell)
                if field and field not in mapping:
                    mapping[field] = col
                elif field == "description":
                    extra_text.append(col)
            if extra_text:
                mapping["more_description"] = extra_text  # type: ignore[assignment]
            score = len([k for k in mapping if k != "more_description"])
            usable = "date" in mapping and ("amount" in mapping or "debit" in mapping or "credit" in mapping)
            if usable and score > best[3]:
                best = (idx, delim, mapping, score)
    if best[0] < 0:
        raise StatementError("no header row with a date and an amount column was found; "
                             "export the statement as CSV with column names")
    return best[0], best[1], best[2]


def parse_amount(value: str) -> Decimal | None:
    if value is None:
        return None
    s = str(value).strip()
    if not s:
        return None
    negative = s.startswith("(") and s.endswith(")")
    s = re.sub(r"[^\d,.\-+]", "", s.replace(" ", "").replace(" ", "").replace(" ", ""))
    if not s or not re.search(r"\d", s):
        return None
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        # Polish exports use a decimal comma; a comma never separates thousands here.
        head, _, tail = s.rpartition(",")
        s = head.replace(",", "") + "." + tail
    try:
        amount = Decimal(s)
    except InvalidOperation:
        return None
    return -abs(amount) if negative else amount


def parse_day(value: str) -> date | None:
    s = (value or "").strip()[:10]
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            continue
    return None


ACCOUNT_RE = re.compile(r"(?:PL)?(?:\d[\s\-]?){26}")
SORT_ACCOUNT_RE = re.compile(r"((?<!\d)\d{2}[-\s]\d{2}[-\s]\d{2}(?!\d)\D{0,30}?)(?<!\d)\d{4}(\d{4})(?!\d)")
DIGITS_RE = re.compile(r"(?<!\d)(?:\d[\s\-]?){12,25}\d(?!\d)")
PESEL_RE = re.compile(r"(?<!\d)\d{11}(?!\d)")


def mask(text: str) -> str:
    """Keep the last four digits of account and card numbers; hide PESEL numbers."""
    def acct(m):
        digits = re.sub(r"\D", "", m.group())
        return f"[account …{digits[-4:]}]" if len(digits) == 26 else m.group()

    def card(m):
        digits = re.sub(r"\D", "", m.group())
        if 13 <= len(digits) <= 19 and record.luhn_valid(digits):
            return f"[card …{digits[-4:]}]"
        return m.group()

    text = ACCOUNT_RE.sub(acct, text or "")
    for start, end, compact in reversed(record.find_ibans(text)):
        text = text[:start] + f"[account …{compact[-4:]}]" + text[end:]
    text = SORT_ACCOUNT_RE.sub(lambda m: f"{m.group(1)}[account …{m.group(2)}]", text)
    text = DIGITS_RE.sub(card, text)
    return PESEL_RE.sub(lambda m: "[PESEL]" if record.pesel_valid(m.group()) else m.group(), text)


def read_statement(path: Path, default_currency: str = "PLN") -> dict:
    text, encoding = read_text(path)
    lines = text.splitlines()
    header_idx, delim, cols = find_header(lines)
    reader = csv.reader(io.StringIO("\n".join(lines[header_idx + 1:])), delimiter=delim)
    rows, skipped = [], []
    for offset, cells in enumerate(reader):
        line_no = header_idx + 2 + offset
        if not any(c.strip() for c in cells):
            continue

        def cell(field):
            i = cols.get(field)
            return cells[i].strip() if i is not None and i < len(cells) else ""

        day = parse_day(cell("date"))
        if "amount" in cols:
            amount = parse_amount(cell("amount"))
        else:
            debit, credit = parse_amount(cell("debit")), parse_amount(cell("credit"))
            amount = None
            if debit is not None and debit != 0:
                amount = -abs(debit)
            elif credit is not None:
                amount = abs(credit)
            elif debit is not None:
                amount = Decimal("0")
        if day is None or amount is None:
            skipped.append({"line": line_no, "reason": "no date or no amount (a summary or note line)"})
            continue
        balance = parse_amount(cell("balance")) if "balance" in cols else None
        rows.append({
            "line": line_no,
            "date": day.isoformat(),
            "amount": f"{amount.quantize(CENT)}",
            "currency": (cell("currency") or default_currency).upper()[:3],
            "description": mask(" · ".join(dict.fromkeys(
                v for v in [cell("description")] + [cells[i].strip() for i in cols.get("more_description", [])
                                                     if i < len(cells)] if v))),
            "counterparty": mask(cell("counterparty")),
            "balance": f"{balance.quantize(CENT)}" if balance is not None else None,
            "type": cell("type") or None,
        })
    if not rows:
        raise StatementError("the header was found, but no transaction rows could be read")
    return {"file": path.name, "encoding": encoding, "delimiter": delim, "header_line": header_idx + 1,
            "columns": sorted(k for k in cols if k != "more_description"), "rows": rows, "skipped": skipped}


# --------------------------------------------------------------------------
# Categories
# --------------------------------------------------------------------------

def load_categories() -> dict:
    with CATEGORIES_FILE.open(encoding="utf-8") as fh:
        return json.load(fh)


def load_household_rules(root: Path | None) -> list[dict]:
    if root is None:
        return []
    p = root / HOUSEHOLD_RULES
    if not p.exists():
        return []
    data = json.loads(p.read_text(encoding="utf-8"))
    return data.get("rules", []) if isinstance(data, dict) else []


def term_re(term: str):
    return re.compile(rf"(?<![a-z0-9]){re.escape(fold(term))}(?![a-z0-9])")


def categorise(rows: list[dict], cats: dict, household: list[dict]) -> None:
    built_in = [(term_re(t), len(fold(t)), r["category"], r.get("sign"), i)
                for i, r in enumerate(cats["rules"]) for t in r["match"]]
    own = [(term_re(r["match"]), r["category"]) for r in household if r.get("match") and r.get("category")]
    for row in rows:
        hay = fold(f"{row['counterparty']} {row['description']}")
        credit = Decimal(row["amount"]) > 0
        chosen, source = None, "none"
        for rx, cat in own:
            if rx.search(hay):
                chosen, source = cat, "household rule"
                break
        if chosen is None:
            best = None
            for rx, length, cat, sign, order in built_in:
                if sign == "credit" and not credit:
                    continue
                if rx.search(hay) and (best is None or (length, -order) > (best[0], -best[2])):
                    best = (length, cat, order)
            if best:
                chosen, source = best[1], "built-in rule"
        if chosen is None:
            chosen = "income" if credit else "other"
            source = "sign" if credit else "none"
        row["category"], row["category_source"] = chosen, source


# --------------------------------------------------------------------------
# Analysis
# --------------------------------------------------------------------------

def month_of(iso: str) -> str:
    return iso[:7]


def months_between(first: date, last: date) -> list[str]:
    out, y, m = [], first.year, first.month
    while (y, m) <= (last.year, last.month):
        out.append(f"{y:04d}-{m:02d}")
        y, m = (y + 1, 1) if m == 12 else (y, m + 1)
    return out


def balance_check(rows: list[dict]) -> dict:
    """Does each balance follow from the previous one? A break means rows are missing."""
    with_bal = [r for r in rows if r["balance"] is not None]
    if len(with_bal) < 2:
        return {"checked": False, "reason": "no balance column"}

    def breaks(seq):
        out = []
        for prev, cur in zip(seq, seq[1:]):
            if Decimal(prev["balance"]) + Decimal(cur["amount"]) != Decimal(cur["balance"]):
                out.append({"after_line": prev["line"], "at_line": cur["line"], "date": cur["date"]})
        return out

    forward, backward = breaks(with_bal), breaks(list(reversed(with_bal)))
    order, found = ("file order", forward) if len(forward) <= len(backward) else ("reverse file order", backward)
    return {"checked": True, "order": order, "breaks": found,
            "note": "each break means transactions are missing between those lines" if found else ""}


def norm_party(row: dict) -> str:
    base = row["counterparty"] or row["description"]
    base = re.sub(r"\[[^\]]*\]", " ", fold(base))
    base = re.sub(r"\d+", " ", base)
    words = [w for w in re.findall(r"[a-z+.&-]+", base) if len(w) > 1][:3]
    return " ".join(words) or "unknown"


PERIODS = [("weekly", 6, 8, Decimal("4.33")), ("monthly", 25, 35, Decimal("1")),
           ("bi-monthly", 55, 65, Decimal("0.5")), ("quarterly", 85, 95, Decimal(1) / Decimal(3)),
           ("yearly", 350, 380, Decimal(1) / Decimal(12))]


def find_recurring(rows: list[dict]) -> list[dict]:
    groups: dict[str, list[dict]] = defaultdict(list)
    for r in rows:
        if Decimal(r["amount"]) < 0:
            groups[norm_party(r)].append(r)
    out = []
    for key, items in groups.items():
        items.sort(key=lambda r: r["date"])
        if len(items) < 2:
            continue
        days = [(date.fromisoformat(b["date"]) - date.fromisoformat(a["date"])).days
                for a, b in zip(items, items[1:])]
        gap = statistics.median(days)
        period = next(((name, factor) for name, lo, hi, factor in PERIODS if lo <= gap <= hi), None)
        if period is None:
            continue
        amounts = [abs(Decimal(i["amount"])) for i in items]
        last, prev = amounts[-1], amounts[-2]
        change = ((last - prev) / prev * 100).quantize(Decimal("0.1")) if prev else Decimal("0")
        out.append({
            "counterparty": items[-1]["counterparty"] or items[-1]["description"],
            "key": key, "period": period[0], "occurrences": len(items),
            "last_amount": f"{last.quantize(CENT)}", "previous_amount": f"{prev.quantize(CENT)}",
            "change_percent": f"{change}", "price_rise": change > Decimal("5"),
            "monthly_equivalent": f"{(last * period[1]).quantize(CENT)}",
            "yearly_equivalent": f"{(last * period[1] * 12).quantize(CENT)}",
            "currency": items[-1]["currency"], "category": items[-1].get("category"),
            "last_date": items[-1]["date"],
            "next_expected": (date.fromisoformat(items[-1]["date"]) + timedelta(days=int(round(gap)))).isoformat(),
        })
    out.sort(key=lambda r: -Decimal(r["monthly_equivalent"]))
    return out


def summarise(rows: list[dict], cats: dict, lang: "dates.Lang") -> dict:
    by_month: dict[tuple, dict] = {}
    by_cat: dict[tuple, Decimal] = defaultdict(Decimal)
    for r in rows:
        key = (month_of(r["date"]), r["currency"])
        m = by_month.setdefault(key, {"in": Decimal(0), "out": Decimal(0), "count": 0})
        amt = Decimal(r["amount"])
        m["in" if amt > 0 else "out"] += amt
        m["count"] += 1
        by_cat[(month_of(r["date"]), r["currency"], r["category"])] += amt
    first = min(date.fromisoformat(r["date"]) for r in rows)
    last = max(date.fromisoformat(r["date"]) for r in rows)
    months = months_between(first, last)
    present = {k[0] for k in by_month}
    label = lambda c: cats["categories"].get(c, {}).get(lang.code) or c  # noqa: E731
    months_out = []
    for mon in months:
        for cur in sorted({k[1] for k in by_month} or {"PLN"}):
            m = by_month.get((mon, cur))
            if m is None:
                continue
            cat_rows = sorted(((c, v) for (mm, cc, c), v in by_cat.items() if mm == mon and cc == cur),
                              key=lambda x: x[1])
            months_out.append({
                "month": mon, "currency": cur, "transactions": m["count"],
                "income": f"{m['in'].quantize(CENT)}", "spending": f"{(-m['out']).quantize(CENT)}",
                "net": f"{(m['in'] + m['out']).quantize(CENT)}",
                "income_text": lang.amount(m["in"], cur), "spending_text": lang.amount(-m["out"], cur),
                "by_category": [{"category": c, "label": label(c), "total": f"{v.quantize(CENT)}",
                                 "total_text": lang.amount(v, cur)} for c, v in cat_rows],
            })
    # A month may be partial when the file starts late in it or stops early in it.
    changes = []
    for cur in sorted({m["currency"] for m in months_out}):
        seq = [m for m in months_out if m["currency"] == cur]
        if len(seq) >= 2:
            prev, last_m = seq[-2], seq[-1]
            pv = {c["category"]: Decimal(c["total"]) for c in prev["by_category"]}
            lv = {c["category"]: Decimal(c["total"]) for c in last_m["by_category"]}
            deltas = []
            for c in set(pv) | set(lv):
                # For income the change is in money received; for everything else, in money spent.
                kind = "income" if c == "income" else "spending"
                before = pv.get(c, Decimal(0)) if kind == "income" else -pv.get(c, Decimal(0))
                after = lv.get(c, Decimal(0)) if kind == "income" else -lv.get(c, Decimal(0))
                d = after - before
                if d:
                    deltas.append({"category": c, "label": label(c), "kind": kind,
                                   "from_month": prev["month"], "to_month": last_m["month"],
                                   "before": f"{before.quantize(CENT)}", "after": f"{after.quantize(CENT)}",
                                   "change": f"{d.quantize(CENT)}", "change_text": lang.amount(d, cur),
                                   "currency": cur})
            deltas.sort(key=lambda x: -abs(Decimal(x["change"])))
            changes.extend(deltas[:6])
    partial = []
    if first.day > 7:
        partial.append(month_of(first.isoformat()))
    if last.day < 21:
        partial.append(month_of(last.isoformat()))
    return {
        "period": {"first": first.isoformat(), "last": last.isoformat(),
                   "first_local": lang.date(first), "last_local": lang.date(last)},
        "months": months_out,
        "changes_last_month": changes,
        "months_without_transactions": [m for m in months if m not in present],
        "partial_months": sorted(set(partial)),
        "currencies": sorted({r["currency"] for r in rows}),
    }


# --------------------------------------------------------------------------
# Commands
# --------------------------------------------------------------------------

def household_root(args) -> Path | None:
    return Path(args.household).expanduser().resolve() if getattr(args, "household", None) else None


def load(args) -> tuple[dict, dict, "dates.Lang"]:
    root = household_root(args)
    stmt = read_statement(Path(args.file).expanduser())
    cats = load_categories()
    categorise(stmt["rows"], cats, load_household_rules(root))
    lang = dates.load_lang(args.lang or record.household_language(root))
    return stmt, cats, lang


def cmd_parse(args) -> dict:
    stmt, cats, lang = load(args)
    return {**stmt, "count": len(stmt["rows"]), "lang": lang.code}


def cmd_summary(args) -> dict:
    stmt, cats, lang = load(args)
    summary = summarise(stmt["rows"], cats, lang)
    warnings = []
    bal = balance_check(stmt["rows"])
    if bal.get("breaks"):
        warnings.append(f"{len(bal['breaks'])} break(s) in the running balance: rows are missing")
    if summary["months_without_transactions"]:
        warnings.append("months with no transactions inside the period: "
                        + ", ".join(summary["months_without_transactions"]) + " (missing, not zero)")
    if summary["partial_months"]:
        warnings.append("these months may be partial (the file starts late or ends early in them): "
                        + ", ".join(summary["partial_months"]))
    if len(summary["currencies"]) > 1:
        warnings.append("several currencies: totals are kept separate")
    uncategorised = sum(1 for r in stmt["rows"] if r["category"] == "other")
    return {"file": stmt["file"], "encoding": stmt["encoding"], "rows": len(stmt["rows"]),
            "skipped_lines": stmt["skipped"], "lang": lang.code, **summary,
            "balance_check": bal, "uncategorised": uncategorised,
            "recurring": find_recurring(stmt["rows"]), "warnings": warnings}


def cmd_recurring(args) -> dict:
    stmt, cats, lang = load(args)
    rec = find_recurring(stmt["rows"])
    for r in rec:
        r["last_amount_text"] = lang.amount(r["last_amount"], r["currency"])
        r["monthly_equivalent_text"] = lang.amount(r["monthly_equivalent"], r["currency"])
    totals: dict = defaultdict(Decimal)
    by_cat: dict = defaultdict(Decimal)
    for r in rec:
        totals[r["currency"]] += Decimal(r["monthly_equivalent"])
        by_cat[(r["currency"], r.get("category") or "other")] += Decimal(r["monthly_equivalent"])
    return {"file": stmt["file"], "lang": lang.code, "recurring": rec,
            "monthly_total": {c: f"{v.quantize(CENT)}" for c, v in totals.items()},
            "monthly_total_text": {c: lang.amount(v, c) for c, v in totals.items()},
            "yearly_total_text": {c: lang.amount(v * 12, c) for c, v in totals.items()},
            "monthly_by_category": [{"currency": c, "category": k, "monthly": f"{v.quantize(CENT)}"}
                                    for (c, k), v in sorted(by_cat.items(), key=lambda x: -x[1])],
            "note": "two occurrences make a guess; three or more make a pattern"}


def cmd_add_rule(args) -> dict:
    root = record.root_of(args.root)
    cats = load_categories()
    if args.category not in cats["categories"]:
        raise StatementError(f"unknown category {args.category!r}; use one of {sorted(cats['categories'])}")
    if args.file:
        try:
            given = json.loads(record.read_text_input(args.file))
        except json.JSONDecodeError as exc:
            raise StatementError(f"the rule is not valid JSON: {exc}")
        args.match = str(given.get("match") or "")
    if not (args.match or "").strip():
        raise StatementError('give the payee or phrase: --file - with {"match": "..."} (text from a '
                             'bank export goes this way), or --match')
    p = root / HOUSEHOLD_RULES
    data = json.loads(p.read_text(encoding="utf-8")) if p.exists() else {"schema_version": 1, "rules": []}
    rule = {"match": args.match.strip(), "category": args.category}
    if rule in data["rules"]:
        return {"note": "the rule already exists", "rule": rule}
    lang = dates.load_lang(args.lang or record.household_language(root))
    summary = lang.log("category_rule", match=args.match.strip(), category=args.category)
    record.require_writable(root, args)
    data["rules"].append(rule)
    change = record.Change(root, lang, "add-rule")
    change.write_json(HOUSEHOLD_RULES, data)
    change.log(summary)
    return record.finish(change, args, {"rule": rule, "file": HOUSEHOLD_RULES.as_posix(),
                                        "summary": summary})


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="statement.py", description=__doc__,
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--version", action="version", version=VERSION)
    sub = p.add_subparsers(dest="command", required=True)
    for name, func, helptext in (("parse", cmd_parse, "every transaction, normalised"),
                                 ("summary", cmd_summary, "totals by month and category, checks"),
                                 ("recurring", cmd_recurring, "payments that repeat")):
        s = sub.add_parser(name, help=helptext)
        s.add_argument("file", help="the CSV export")
        s.add_argument("--household", help="the household folder, for its category rules and language")
        s.add_argument("--lang", help="en or pl; default: the profile's language, else English")
        s.set_defaults(func=func)
    s = sub.add_parser("add-rule", help="teach a category for a counterparty or phrase")
    s.add_argument("root", help="the household folder")
    s.add_argument("--match", help="the payee or phrase; text from a bank export goes with --file - instead")
    s.add_argument("--file", help='the rule as JSON ({"match": "..."}), or - for stdin')
    s.add_argument("--category", required=True)
    s.add_argument("--approved-by")
    s.add_argument("--dry-run", action="store_true")
    s.add_argument("--today")
    s.add_argument("--lang")
    s.set_defaults(func=cmd_add_rule)
    s = sub.add_parser("commit", help="apply a previewed rule after a yes")
    s.add_argument("root", help="the household folder")
    s.add_argument("--confirm", required=True, help="the token printed with the preview")
    s.add_argument("--approved-by", required=True, help="the name of the person who said yes")
    s.add_argument("--today")
    s.set_defaults(func=record.cmd_commit)
    return p


def emit(obj: dict, code: int = 0) -> int:
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    obj.setdefault("ok", code == 0)
    obj.setdefault("calculated_by", f"statement.py {VERSION}")
    print(json.dumps(obj, ensure_ascii=False, indent=2))
    return code


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        return emit(args.func(args))
    except (StatementError, record.RecordError, dates.InputError, OSError) as exc:
        return emit({"ok": False, "errors": [str(exc)]}, 1)


if __name__ == "__main__":
    sys.exit(main())
